$ProgressPreference = 'SilentlyContinue'
Add-Type -AssemblyName System.IO.Compression
$input = [System.IO.MemoryStream]::new([Convert]::FromBase64String(''))
$gzip = [System.IO.Compression.GZipStream]::new($input, [System.IO.Compression.CompressionMode]::Decompress)
$output = [System.IO.MemoryStream]::new()
$gzip.CopyTo($output)
New-Item -ItemType Directory -Force 'C:\wsm' | Out-Null
[IO.File]::WriteAllBytes('C:\wsm\deskcap.ps1', $output.ToArray())
Write-Output ('pushed file, bytes = ' + (Get-Item 'C:\wsm\deskcap.ps1').Length)
